struct Visitor {                            // a class, not an interface: defaults are inherited
    virtual ~Visitor() = default;
    virtual void visit(const Element& e) { throw std::runtime_error{"unhandled element"}; }
    virtual void visit(const Circle& c)  { visit(static_cast<const Element&>(c)); }
};

struct UnionCircle : Circle {               // element extension
    void accept(Visitor& v) const override {
        if (auto* uv = dynamic_cast<UnionVisitor*>(&v)) uv->visit(*this);  // sideways probe
        else v.visit(static_cast<const Element&>(*this));                  // old visitor
    }
};
